  assign m_level[50] = vis_a[3:2] == vis_b[3:2] && vis_a[7:6] == vis_b[7:6];
  assign m_data[50] = vis_a[5:4] == {1'b1, byte1[0]};  // byte1.bit0, push-pull
  assign m_sub[50] = sub_a[4] == out_a[1] && sub_a[5] == out_a[1] && sub_a[6] == out_a[1] && sub_a[7] == out_a[1] && sub_a[8] == out_a[2] && sub_a[9] == out_a[2] && sub_a[10] == out_a[2] && sub_a[11] == out_a[2] && sub_a[12] == out_a[3] && sub_a[13] == out_a[3] && sub_a[14] == out_a[3] && sub_a[15] == out_a[3];
  assign m_level[51] = vis_a[3:2] == 2'b11 && vis_a[5:4] == vis_b[5:4] && vis_a[7:6] == vis_b[7:6];
  assign m_data[51] = 1'b1;
  assign m_sub[51] = sub_a[4] == out_a[1] && sub_a[5] == out_a[1] && sub_a[6] == out_a[1] && sub_a[7] == out_a[1] && sub_a[8] == out_a[2] && sub_a[9] == out_a[2] && sub_a[10] == out_a[2] && sub_a[11] == out_a[2] && sub_a[12] == out_a[3] && sub_a[13] == out_a[3] && sub_a[14] == out_a[3] && sub_a[15] == out_a[3];
  assign m_level[52] = vis_a[3:2] == 2'b10 && vis_a[5:4] == vis_b[5:4] && vis_a[7:6] == vis_b[7:6];
  assign m_data[52] = 1'b1;
  assign m_sub[52] = sub_a[4] == out_a[1] && sub_a[5] == out_a[1] && sub_a[6] == out_a[1] && sub_a[7] == out_a[1] && sub_a[8] == out_a[2] && sub_a[9] == out_a[2] && sub_a[10] == out_a[2] && sub_a[11] == out_a[2] && sub_a[12] == out_a[3] && sub_a[13] == out_a[3] && sub_a[14] == out_a[3] && sub_a[15] == out_a[3];
  assign m_level[53] = vis_a[7:6] == 2'b11 && vis_a[3:2] == vis_b[3:2] && vis_a[5:4] == vis_b[5:4];
  assign m_data[53] = 1'b1;
  assign m_sub[53] = sub_a[4] == out_a[1] && sub_a[5] == out_a[1] && sub_a[6] == out_a[1] && sub_a[7] == out_a[1] && sub_a[8] == out_a[2] && sub_a[9] == out_a[2] && sub_a[10] == out_a[2] && sub_a[11] == out_a[2] && sub_a[12] == out_a[3] && sub_a[13] == out_a[3] && sub_a[14] == out_a[3] && sub_a[15] == out_a[3];
  reg [3:0] deadline; reg has_deadline;
  always @(*) begin
    has_deadline = 1'b1;
    case (astate)
      6'd0: deadline = 4'd0;
      6'd1: deadline = 4'd1;
      6'd2: deadline = 4'd2;
      6'd3: deadline = 4'd2;
      6'd4: deadline = 4'd6;
      6'd5: deadline = 4'd8;
      6'd6: deadline = 4'd2;
      6'd7: deadline = 4'd6;
      6'd8: deadline = 4'd8;
      6'd9: deadline = 4'd2;
      6'd10: deadline = 4'd6;
      6'd11: deadline = 4'd8;
      6'd12: deadline = 4'd2;
      6'd13: deadline = 4'd6;
      6'd14: deadline = 4'd8;
      6'd15: deadline = 4'd2;
      6'd16: deadline = 4'd6;
      6'd17: deadline = 4'd8;
      6'd18: deadline = 4'd2;
      6'd19: deadline = 4'd6;
      6'd20: deadline = 4'd8;
      6'd21: deadline = 4'd2;
      6'd22: deadline = 4'd6;
      6'd23: deadline = 4'd8;
      6'd24: deadline = 4'd2;
      6'd25: deadline = 4'd6;
      6'd26: deadline = 4'd8;
      6'd27: deadline = 4'd2;
      6'd28: deadline = 4'd2;
      6'd29: deadline = 4'd2;
      6'd30: deadline = 4'd6;
      6'd31: deadline = 4'd8;
      6'd32: deadline = 4'd2;
      6'd33: deadline = 4'd6;
      6'd34: deadline = 4'd8;
      6'd35: deadline = 4'd2;
      6'd36: deadline = 4'd6;
      6'd37: deadline = 4'd8;
      6'd38: deadline = 4'd2;
      6'd39: deadline = 4'd6;
      6'd40: deadline = 4'd8;
      6'd41: deadline = 4'd2;
      6'd42: deadline = 4'd6;
      6'd43: deadline = 4'd8;
      6'd44: deadline = 4'd2;
      6'd45: deadline = 4'd6;
      6'd46: deadline = 4'd8;
      6'd47: deadline = 4'd2;
      6'd48: deadline = 4'd6;
      6'd49: deadline = 4'd8;
      6'd50: deadline = 4'd2;
      6'd51: deadline = 4'd6;
      6'd52: deadline = 4'd8;
      6'd53: deadline = 4'd2;
