  always @(*) if (step) begin
    events: assert (!event_ || (m_where & m_gap) != 54'd0);
    levels: assert (event_ ? (m_where & m_level) != 54'd0 : (vis_a & VCH) == (vis_b & VCH));
    data: assert (!event_ || (m_where & m_data) != 54'd0);
    subslot: assert (event_ ? (m_where & m_sub) != 54'd0 : (sub_a[4] == out_a[1] && sub_a[5] == out_a[1] && sub_a[6] == out_a[1] && sub_a[7] == out_a[1] && sub_a[8] == out_a[2] && sub_a[9] == out_a[2] && sub_a[10] == out_a[2] && sub_a[11] == out_a[2] && sub_a[12] == out_a[3] && sub_a[13] == out_a[3] && sub_a[14] == out_a[3] && sub_a[15] == out_a[3]));
