  always @(*) if (step) slots: assert (!event_ || (m_where & m_slot) != 54'd0);
  always @(*) slots_ante: cover (done);
`endif
  // antecedents: the certificate's last state (state 54) is reached
  always @(*) events_ante: cover (done);
  always @(*) levels_ante: cover (done);
  always @(*) data_ante: cover (done);
  always @(*) subslot_ante: cover (done);
  always @(*) deadline__ante: cover (done);
  always @(*) quiet_ante: cover (done);
  always @(*) page_ante: cover (done);
  always @(*) final_54: cover (fin_54);
